  unitAdvertising: { ru: 'Реклама', en: 'Advertising' },
  unitRevenue: { ru: 'ARPU (выручка с подписчика)', en: 'ARPU (revenue per subscriber)' },
  unitCdn: { ru: 'Трафик ({hours} ч × {perHour} ₽)', en: 'Bandwidth ({hours} h × ₽{perHour})' },
  unitSupport: { ru: 'Поддержка и биллинг', en: 'Support and billing' },
  unitContribution: { ru: 'Вклад с подписчика', en: 'Contribution per subscriber' },
  unitNote: { ru: 'Обратите внимание: контента в этой таблице нет. Он не переменный расход — он постоянный, и потому определяет не выгодность подписчика, а необходимый масштаб.', en: 'Note what is missing: content. It is not a variable cost but a fixed one, so it does not decide whether a subscriber is worth having — it decides what scale you need.' },
  unitBreakEven: { ru: 'При постоянных расходах {fixed}/мес точка безубыточности — <b>{subs} подписчиков</b> (сейчас {current}).', en: 'At fixed costs of {fixed}/mo, break-even is <b>{subs} subscribers</b> (currently {current}).' },
  unitNoBreakEven: { ru: 'Вклад с подписчика ≤ 0: точки безубыточности не существует ни при каком масштабе. Сначала чините экономику, потом растите.', en: 'Contribution per subscriber is ≤ 0, so break-even does not exist at any scale. Fix the economics first, then grow.' },
  unitAcquisition: { ru: 'Привлечение подписчика', en: 'Subscriber acquisition' },
  unitCac: { ru: 'CAC (маркетинг / новые подписчики)', en: 'CAC (marketing / new subscribers)' },
  unitLifetime: { ru: 'Срок жизни подписки', en: 'Subscription lifetime' },
  unitLifetimeValue: { ru: '{value} мес.', en: '{value} mo.' },
  unitLtv: { ru: 'LTV (вклад за всё время жизни)', en: 'LTV (lifetime contribution)' },
  unitLtvCacNote: { ru: 'Ориентир индустрии: LTV/CAC ≥ 3. В стриминге эта величина обманчива: она не учитывает контент, без которого подписчик не остался бы ни на месяц.', en: 'The industry benchmark is LTV/CAC ≥ 3. In streaming the number is deceptive: it ignores the content without which the subscriber would not have stayed a single month.' },

